package com.smarthire.service;
import com.smarthire.dto.JobRequest; import com.smarthire.entity.Job; import com.smarthire.entity.User; import com.smarthire.enums.Role; import com.smarthire.repository.JobRepository; import com.smarthire.repository.UserRepository; import java.util.List; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.web.server.ResponseStatusException;
@Service public class JobService { private final JobRepository jobs; private final UserRepository users; public JobService(JobRepository jobs,UserRepository users){this.jobs=jobs;this.users=users;} public Job create(String email,JobRequest r){User u=recruiter(email);return jobs.save(new Job(u.getId(),r.title(),r.companyName(),r.location(),r.jobType(),r.workMode(),r.description(),r.requirements(),r.salaryRange()));} public List<Job> list(){return jobs.findByActiveTrueOrderByCreatedAtDesc();} public List<Job> mine(String email){return jobs.findByRecruiterIdOrderByCreatedAtDesc(recruiter(email).getId());} public Job get(Long id){return jobs.findById(id).filter(Job::isActive).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Job not found."));} public Job update(String email,Long id,JobRequest r){Job job=owned(email,id);job.update(r.title(),r.companyName(),r.location(),r.jobType(),r.workMode(),r.description(),r.requirements(),r.salaryRange());return jobs.save(job);} public void deactivate(String email,Long id){Job job=owned(email,id);job.deactivate();jobs.save(job);} private Job owned(String email,Long id){User user=recruiter(email);Job job=jobs.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Job not found."));if(!job.getRecruiterId().equals(user.getId()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"You can manage only your jobs.");return job;} private User recruiter(String email){User u=users.findByEmail(email).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED));if(u.getRole()!=Role.RECRUITER)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only recruiters can manage jobs.");return u;}}
